// Missed Call Text-Back Engine: Suppression Check & Template Selection
const body = $input.first().json.body || $input.first().json;

const callerPhone = (body.caller_phone || body.phone || '').trim();
const callerName = (body.caller_name || 'there').trim();
const isAfterHours = Boolean(body.is_after_hours !== undefined ? body.is_after_hours : false);
const isSuppressed = Boolean(body.suppressed || body.is_opted_out || false);
const callDuration = Number(body.call_duration_seconds || 0);

// 1. Mandatory Suppression & Opt-Out Gate
if (!callerPhone || isSuppressed) {
  return [{
    json: {
      status: 'SUPPRESSED',
      caller_phone: callerPhone || 'UNKNOWN',
      textback_dispatched: false,
      suppression_blocked: true,
      reason: !callerPhone ? 'MISSING_CALLER_PHONE' : 'CONTACT_SUPPRESSED_OR_OPTED_OUT',
      processed_at: new Date().toISOString()
    }
  }];
}

// 2. Select Approved Messaging Template
let messageBody = '';
if (isAfterHours) {
  messageBody = `Hi ${callerName}, thanks for calling! Our team is currently off the line, but we received your call. Reply to this text with what you need, or pick a consultation time here: {{ $env.AGENCY_WEBHOOK_URL }}/schedule`;
} else {
  messageBody = `Hi ${callerName}, thanks for calling! We are assisting another client right now. How can we help you today? Reply to this text and our advisor will assist you immediately.`;
}

return [{
  json: {
    status: 'PROCESSED',
    caller_phone: callerPhone,
    caller_name: callerName,
    is_after_hours: isAfterHours,
    textback_dispatched: true,
    suppression_blocked: false,
    delivery_status: 'DISPATCHED_TO_GATEWAY',
    message_preview: messageBody,
    crm_logged: true,
    processed_at: new Date().toISOString()
  }
}];
